const DATA={"pt": {"tag": "Independente · FR / PT / ES", "nav": ["Serviços", "Como funciona", "Sobre mim"], "talk": "Contactar", "hero": "Apoio ao cliente em francês e espanhol", "intro": "Sou a Romina, a sua interlocutora para o acompanhamento de clientes.", "cta": "Contactar", "problemTitle": "Quando a língua cria distância.", "problem": "Muitas relações comerciais passam por um inglês que nenhuma das partes fala como língua materna. Perdem-se nuances, o tom pode soar frio e o cliente sente distância. Isso pode pôr renovações em risco.", "what": "Os meus serviços", "tasks": ["Comunico com os seus clientes importantes na língua materna deles, em nome da sua marca.", "Acompanho cada conta de perto: pedidos, seguimento e renovações.", "Preparo reuniões e negociações, com briefing cultural para a sua equipa.", "Adapto textos e propostas ao tom de cada cliente.", "Dou-lhe um relatório mensal: estado de cada conta, riscos e próximas ações."], "who": "Para quem é", "yes": "É para si se", "yesText": "Tem clientes de língua francesa ou espanhola e procura uma pessoa dedicada à comunicação e ao acompanhamento dos pedidos.", "no": "Não é para si se", "noText": "Procura atendimento em massa, prospeção comercial ou tradução certificada.", "how": "Começamos de forma simples", "steps": ["Conversamos durante 15 minutos sobre os seus clientes e as suas necessidades.", "Combinamos as línguas, os canais e a frequência do acompanhamento.", "Assumo o acompanhamento e envio-lhe um resumo do trabalho feito e dos pontos a melhorar."], "offersTitle": "Formas de começar", "quote": "Sob consulta", "offers": [["Primeira colaboração", "Oferta de lançamento", "Em 2 horas, revejo as suas mensagens automáticas em francês ou espanhol. Entrego-lhe as versões corrigidas e indico os pontos que merecem atenção. Este preço de lançamento aplica-se às 3 primeiras colaborações. Preço habitual: 60 €.", "30 €", "2 h", ""], ["Pacote de acompanhamento", "Acompanhamento mensal", "Gestão de e-mails, tratamento de reclamações e fidelização em francês e espanhol.", "300 €", "10 h/mês", ""], ["À medida", "Consoante as suas necessidades", "Se precisar de mais horas ou de vários canais de comunicação, preparo um orçamento à medida.", "Por orçamento", "", ""]], "offerCta": "Conversar sobre esta opção", "work": "As ferramentas que utilizo", "principles": ["Sempre a mesma interlocutora responsável.", "Tarefas, horários e volume de trabalho acordados em conjunto.", "Confidencialidade e tratamento de dados acordados por escrito, nos termos do RGPD.", "Quando acordado, a IA pode apoiar a preparação de rascunhos. Revejo cada mensagem antes de a utilizar."], "about": "Sou a Romina.", "bio": "Entre Portugal, a Venezuela e a França, aprendi a prestar atenção às nuances, às expectativas e às diferentes formas de comunicar. Na onebyonecx, ponho essa experiência ao serviço das suas relações com clientes noutros mercados.", "career": "Com formação em Ciências da Comunicação e Publicidade, criei a onebyonecx para reunir línguas, comunicação intercultural e acompanhamento de clientes. Sou a interlocutora da sua empresa e dos seus parceiros.", "variants": "Trabalho em francês, português e espanhol. Antes de começar, combinamos as variantes linguísticas, o tom e os canais de comunicação. Faço a coordenação e envio os relatórios em francês. Sou portuguesa, venezuelana de coração e vivo em Paris. Conheço estas culturas por dentro.", "example": "A mesma intenção. Outra proximidade.", "illustrative": "Exemplo ilustrativo · não é um caso de cliente", "before": "E-mail inicial em inglês", "after": "Versão adaptada em espanhol", "explain": "A versão adaptada contextualiza o pedido, abre espaço a dúvidas e propõe um próximo passo. O tom depende da pessoa, da relação e do contexto, não apenas do país.", "faq": "Perguntas sobre o acompanhamento de clientes", "faqs": [["A quem se destina este serviço de acompanhamento de clientes?", "A microempresas, PME e profissionais independentes que precisam de comunicar com os seus clientes em francês ou espanhol. Acompanho os seus clientes atuais, desde os pedidos e orçamentos até aos contactos após a venda. Definimos em conjunto os clientes e as tarefas a acompanhar."], ["Posso contratar apoio ao cliente por poucas horas por mês?", "Sim. A primeira colaboração inclui 2 horas por um total de 30 €, em vez de 60 €. Esta oferta está limitada às 3 primeiras missões. O pacote mensal inclui 10 horas por 300 €. Para mais horas ou vários canais, apresento um orçamento antes de começar."], ["É um serviço de assistente virtual ou de centro de atendimento?", "À distância, realizo tarefas de assistência virtual ligadas aos seus clientes: e-mails, mensagens, acompanhamento de pedidos e atualização de informações. Sou a sua interlocutora externa dedicada, com horários e um volume de trabalho acordados. Não presto serviços de centro de atendimento nem faço prospeção comercial."], ["Pode acompanhar clientes ou um grupo presencialmente?", "Sim, mediante disponibilidade. Facilito o acolhimento e a comunicação prática em francês ou espanhol entre os seus clientes e a sua equipa. O local, a duração, o número de participantes e a deslocação são acordados antes do serviço. Não se trata de interpretação médica nem de tradução certificada."], ["Pode dar seguimento a um orçamento em francês ou espanhol?", "Sim. Confirmo que o cliente recebeu o orçamento, recolho as suas dúvidas e consulto a sua equipa antes de comunicar um preço, um prazo ou um compromisso. Registo o estado da conversa e a próxima etapa."], ["Quem aprova as decisões e protege os dados dos clientes?", "Definimos por escrito os acessos, a confidencialidade e as regras de aprovação. Os preços e os compromissos comerciais ficam sob o seu controlo. Qualquer utilização de IA respeita as condições acordadas e inclui revisão humana."]], "contact": "Contactar", "contactIntro": "Tem alguma pergunta ou precisa de apoio no acompanhamento dos seus clientes?", "fields": ["Nome", "Empresa", "E-mail profissional", "Mercado ou língua prioritária", "Que tipo de apoio procura, à distância ou presencial?"], "send": "Abrir na minha aplicação de e-mail", "missing": "Este formulário prepara um e-mail para a Romina. Confirme o envio na sua aplicação de e-mail. O site não envia nem guarda os dados do formulário.", "email": "hernandezfsantos@gmail.com", "required": "Os campos assinalados com um asterisco (*) são obrigatórios. Não inclua dados confidenciais dos seus clientes.", "privacy": "Privacidade", "legal": "Menções legais", "draft": "Informações por completar antes da abertura ao público.", "legalBody": ["Responsável: Romina Hernandez · onebyonecx. Nome legal completo e estatuto da atividade: por confirmar.", "Contacto: hernandezfsantos@gmail.com · WhatsApp: +33 7 81 66 32 25. Morada profissional e número de registo (SIREN/RCS, quando aplicável): por confirmar.", "Número de IVA, quando aplicável, e responsável pela publicação: por confirmar.", "Identidade, morada e telefone do prestador de alojamento: por confirmar."], "privacyBody": ["Pode contactar a Romina por e-mail ou WhatsApp. O formulário apenas prepara uma mensagem na sua aplicação de correio: o envio depende da sua confirmação nessa aplicação. O site não transmite nem guarda o conteúdo do formulário.", "Ao enviar um e-mail ou abrir o WhatsApp, utiliza serviços externos sujeitos às respetivas políticas de privacidade. Não foi integrado nenhum widget de conversação, serviço de análise de audiência ou publicidade.", "Serão também indicados os meios para exercer os direitos de acesso, retificação, apagamento, limitação, oposição e portabilidade, quando aplicáveis, e apresentar reclamação à CNIL.", "O alojamento e o controlo de acesso podem tratar dados técnicos segundo as regras do respetivo prestador; esses detalhes têm de ser confirmados."], "back": "Voltar ao início", "pause": "Pausar vídeo", "play": "Reproduzir vídeo", "select": "Idioma", "option": "Opção de interesse", "sector": "Precisa de acompanhar clientes em francês ou espanhol, mas não tem uma pessoa dedicada a essa comunicação? Trabalho em ligação com a sua equipa.", "tourServices": [["Resposta a pedidos", "Faço a gestão dos e-mails e respondo aos pedidos dos seus clientes em francês e espanhol.", ""], ["Acompanhamento de reclamações", "Ouço os seus clientes, respondo-lhes e acompanho cada reclamação até estar resolvida.", ""], ["Fidelização de clientes", "Mantenho o contacto com os seus clientes e recolho as suas opiniões para ajudar a melhorar o seu serviço.", ""]], "journey": "Compreender. Adaptar. Criar ligação. Cuidar da relação.", "stages": [["Compreender", "Os seus serviços, valores e as expectativas de quem comunica consigo: começo por conhecer o contexto."], ["Adaptar", "O tom, o vocabulário e as explicações ajustam-se à pessoa e ao mercado."], ["Criar ligação", "Propostas, dúvidas e reuniões: cada contacto tem resposta e um próximo passo."], ["Cuidar da relação", "Pós-venda, feedback e contactos regulares para manter o diálogo aberto."]], "cultureTitle": "É aqui que começa uma relação de confiança.", "cultureText": "A confiança constrói-se na forma de ouvir, explicar e dar seguimento. Represento a sua empresa com uma comunicação clara e próxima, para que os seus parceiros se sintam compreendidos e saibam o que esperar.", "scope": "Uma extensão da sua equipa.", "scopeText": "Para pequenas empresas e profissionais que precisam de delegar a gestão de e-mails, o apoio ao cliente e o acompanhamento de relações em francês e espanhol.", "scopeNote": "A decisão comercial continua consigo: preços, compromissos, condições e alterações seguem as suas regras. Reuniões e eventos presenciais mediante disponibilidade e orçamento.", "offerTitle": "Preços", "offerNote": "O número de horas, os canais de comunicação e as eventuais despesas de deslocação ficam definidos no orçamento antes de começarmos.", "fit": "França · Espanha · América Latina", "brandLine": "Comunicação clara. Acompanhamento próximo. Relações cuidadas.", "seoTitle": "Apoio ao cliente em francês e espanhol | onebyonecx", "seoDescription": "Apoio ao cliente em francês e espanhol para plataformas e PME: gestão de e-mails, tratamento de reclamações e fidelização.", "identity": "Três línguas, uma pessoa", "proof": "Os contactos são acompanhados. As decisões continuam consigo.", "trustTitle": "Acompanhamento próximo. Regras claras.", "trusts": [["Uma interlocutora dedicada", "A Romina acompanha os contactos e conhece a sua empresa, as suas ofertas e os seus parceiros."], ["Um âmbito acordado", "Definimos tarefas, línguas, canais, volume, horários e prazos de resposta em conjunto."], ["As decisões continuam consigo", "Preços, condições e compromissos ficam sob o seu controlo. Encaminho o que precisa da sua aprovação."], ["Trabalho com visibilidade", "Um relatório mensal apresenta os contactos acompanhados, os bloqueios e as próximas ações."]], "trustNote": "Uma só interlocutora. Âmbito, horários, acessos e confidencialidade acordados por escrito. Os preços e os compromissos comerciais dependem da sua aprovação.", "blogTitle": "Conselhos para comunicar e acompanhar clientes", "blogIntro": "Sugestões práticas sobre apoio ao cliente, acompanhamento de propostas e comunicação intercultural em francês e espanhol.", "read": "Ler as sugestões", "backHome": "Início", "blogPosts": [["Como dar seguimento a uma proposta por e-mail", "Uma mensagem clara recorda o contexto e propõe um próximo passo.", ["Identifique a proposta ou o orçamento e confirme a receção.", "Faça uma pergunta concreta: falta esclarecer os serviços incluídos, os prazos ou as condições?", "Combine o próximo contacto. A ausência de resposta, por si só, não prova falta de interesse."]], ["Comunicação intercultural: adaptar o tom ao cliente", "A cultura dá pistas; a pessoa e o contexto orientam a comunicação.", ["Observe como o cliente se dirige a si e qual é o seu canal de comunicação preferido.", "Confirme as expectativas de formalidade, sem as deduzir apenas da nacionalidade.", "Mantenha os factos e os compromissos em todas as línguas. Adapte o vocabulário e as explicações para facilitar a compreensão."]], ["Como organizar o acompanhamento de clientes", "Um registo partilhado ajuda a equipa a acompanhar os pedidos pendentes.", ["Registe o assunto, a data do último contacto e a pessoa responsável.", "Distinga as dúvidas por esclarecer, as decisões necessárias e a próxima data de contacto.", "Separe os factos confirmados das interpretações e recomendações no resumo de acompanhamento."]]], "serviceCta": "Falar sobre este apoio", "videoLine": "Falamos a língua deles. Compreendemos a cultura deles.", "menuLabel": "Menu", "menuClose": "Fechar menu", "discover": "Ver os meus serviços", "caseLabel": "Uma situação do dia a dia · exemplo ilustrativo", "caseTitle": "Como dar seguimento a uma proposta em espanhol?", "caseIntro": "Um distribuidor no México pediu um orçamento à sua empresa portuguesa. Passou uma semana e ainda não respondeu.", "caseSteps": [["Retomo o contacto", "Confirmo se recebeu a proposta e pergunto o que precisa de esclarecer, em espanhol."], ["Levo a dúvida à sua equipa", "Se a questão for sobre preço ou prazo, recolho a resposta antes de assumir qualquer compromisso."], ["Dou continuidade", "Partilho a resposta, combino o próximo contacto e deixo o estado da oportunidade registado."]], "caseMessage": "Hola, María. Le escribo para dar seguimiento al presupuesto que le enviamos la semana pasada. ¿Le gustaría aclarar algún punto sobre los plazos o las condiciones? Puedo confirmar los detalles con nuestro equipo.", "messageLabel": "Exemplo de mensagem em espanhol", "caseNote": "A comunicação intercultural ajuda a ajustar a abordagem e o tom à pessoa e à relação. O acompanhamento tem em conta o contexto, sem fórmulas por nacionalidade.", "toolNav": "Oficina intercultural", "clientFollowup": {"title": "Ferramentas e forma de trabalhar", "rows": [["Comunicação", "E-mail, WhatsApp, telefone e videochamada."], ["Organização", "Histórico dos contactos, quadro de acompanhamento partilhado e ferramentas da sua empresa, conforme o âmbito acordado."], ["Resumo", "Ações realizadas, pedidos pendentes e decisões a validar. Frequência definida em conjunto."], ["Deslocações", "Local, duração, número de participantes e despesas de deslocação acordados antes da missão."]]}, "servicesIntro": "Gestão de e-mails, acompanhamento da carteira de clientes e apoio multilingue presencial, com comunicação adaptada a cada relação.", "workshopToggle": "Tradução e adaptação cultural de mensagens", "personalLabel": "Apoio ao cliente em francês e espanhol", "personalQuote": "Aprendi que as pessoas esquecem o que disseste, esquecem o que fizeste, mas nunca esquecem como as fizeste sentir.", "launchRate": "", "blogMetaTitle": "Apoio ao cliente e comunicação intercultural | onebyonecx", "blogMetaDescription": "Sugestões práticas sobre apoio ao cliente, acompanhamento de propostas e comunicação intercultural em francês e espanhol.", "videoTitle": "Apoio ao cliente em <em>francês e espanhol</em>", "videoPromise": "Ajudo a sua equipa a comunicar com os clientes na língua deles, com um tom adequado a cada situação.", "videoLabel": "À distância e presencialmente", "videoCta": "Contactar", "whatsappCta": "Falar com a Romina no WhatsApp", "whatsappMessage": "Olá, Romina. Vi a onebyonecx e gostaria de saber mais sobre o acompanhamento de clientes.", "contactAvailability": "Envie-me uma mensagem por e-mail ou pelo WhatsApp. Responderei assim que possível.", "emailCta": "Escrever um e-mail", "mailSubject": "Pedido de contacto — onebyonecx", "mailStatus": "Confirme o envio na sua aplicação de e-mail. Se a aplicação não abrir, utilize o endereço indicado acima.", "privacyContact": "Pode contactar a Romina por e-mail ou WhatsApp. O formulário apenas prepara uma mensagem na sua aplicação de correio: o envio depende da sua confirmação nessa aplicação. O site não transmite nem guarda o conteúdo do formulário.", "privacyProvider": "Ao enviar um e-mail ou abrir o WhatsApp, utiliza serviços externos sujeitos às respetivas políticas de privacidade. Não foi integrado nenhum widget de conversação, serviço de análise de audiência ou publicidade.", "legalContact": "Contacto: hernandezfsantos@gmail.com · WhatsApp: +33 7 81 66 32 25. Morada profissional e número de registo (SIREN/RCS, quando aplicável): por confirmar.", "messageLang": "es", "situations": {"eyebrow": "Em que situações pode contar comigo?", "title": "É este o seu caso?", "intro": "Exemplos concretos do apoio que posso prestar à sua empresa.", "illustrative": "Exemplos fictícios para ilustrar o serviço.", "scenarioLabel": "A sua situação", "actionLabel": "O que posso fazer", "prev": "Exemplo anterior", "next": "Exemplo seguinte", "choose": "Contactar sobre este serviço", "swipe": "Deslize os cartões para descobrir os exemplos", "request": "Gostaria de saber mais sobre este apoio: ", "items": [{"title": "A sua IA responde, mas o cliente não se sente compreendido.", "action": "Revejo as suas mensagens automáticas em francês e espanhol para tornar a resposta mais clara, adaptar o tom e identificar promessas que a sua equipa ainda não pode confirmar.", "category": "", "scenario": "", "steps": "", "note": "", "revision": {"title": "Exemplo de revisão em espanhol", "beforeLabel": "Mensagem automática", "afterLabel": "Depois da revisão", "before": "Su pedido está en proceso. Espere una actualización.", "after": "Lamento el retraso en la entrega de su pedido. Voy a comprobar qué ha pasado con el envío y le escribiré en cuanto tenga más información.", "reason": "Reconheci o atraso e indiquei o próximo passo, sem prometer um prazo que ainda não foi confirmado.", "language": "es"}}, {"title": "As suas respostas estão traduzidas, mas não adaptadas.", "action": "Uma mensagem correta em português pode parecer fria em francês ou espanhol. Adapto o tom, para além das palavras.", "category": "", "scenario": "", "steps": "", "note": ""}, {"title": "Os seus clientes escrevem… e ficam à espera.", "action": "Assumo a gestão da caixa de e-mail e dos pedidos, para que cada cliente receba uma resposta clara e humana.", "category": "", "scenario": "", "steps": "", "note": ""}]}, "audienceTitle": "Para quem?", "audience": "Trabalho com plataformas e serviços online que têm clientes de língua francesa ou espanhola, em áreas como a formação, a tecnologia financeira, a saúde digital e o software por subscrição. Pode contar com o meu apoio para acompanhar esses clientes, mesmo que só precise de algumas horas por mês.", "onsite": "A pedido, o acompanhamento pode ser presencial ou por videochamada.", "illustratedTitle": "Um exemplo concreto", "illustrated": "Um cliente que escreve em espanhol pagou um curso, mas ainda não consegue aceder à plataforma. A resposta automática diz apenas «Su solicitud está en trámite». Eu responderia «Lamento que aún no pueda acceder al curso. Voy a comprobar qué ha ocurrido y le escribiré hoy antes de las 17:00 para informarle». Reconheço o problema, mantenho o tratamento formal já usado na conversa e indico quando voltarei a contactar o cliente. Depois, confirmo o que aconteceu com a equipa e acompanho o pedido até o acesso ficar resolvido.", "workingCopy": ["Respondo aos seus clientes e acompanho os pedidos com as ferramentas que a sua equipa já utiliza, como o e-mail, o WhatsApp Business, o chat ou o CRM.", "Se precisar, também preparo apresentações, guias de boas-vindas e fichas práticas no Canva, de acordo com a identidade visual da sua empresa."], "closeTitle": "Um cliente que se sente compreendido é um cliente que fica.", "closeCopy": "Falemos sobre o apoio de que precisa para acompanhar os seus clientes em francês e espanhol.", "bioExtra": "Portuguesa, venezuelana de coração e a viver em Paris: conheço estas culturas por dentro.", "cookies": "Cookies", "cookiesTitle": "Cookies e armazenamento local", "cookiesBody": ["O código da onebyonecx não instala cookies publicitários nem ferramentas de medição de audiência. Não estão integrados o Google Analytics, o píxel da Meta ou módulos de rastreio de redes sociais.", "As fotografias, o ficheiro de vídeo e os tipos de letra estão alojados com o site. O vídeo não utiliza um leitor incorporado do YouTube ou do Vimeo. A língua é definida pelo endereço da página, sem criar um cookie de preferência.", "O armazenamento de sessão « onebyone-review-brief » serve apenas para transferir um resumo da Oficina intercultural para o formulário de contacto quando pede uma revisão humana. Contém o resumo preparado, permanece no seu navegador e é eliminado depois de ser inserido no formulário ou quando termina a sessão do separador. Como a análise por IA está atualmente desativada, não são gerados resultados automáticos.", "As ligações de e-mail e WhatsApp só abrem serviços externos quando as utiliza. Esses serviços aplicam as suas próprias regras de privacidade e de cookies. Não é carregado na página nenhum módulo externo de conversação do WhatsApp.", "A plataforma de alojamento e de controlo de acesso pode utilizar mecanismos técnicos de segurança e autenticação. Estes são geridos pela plataforma, independentemente do código do site. Os seus nomes e prazos de conservação não são definidos pela onebyonecx.", "Esta versão não disponibiliza cookies opcionais, pelo que não há escolhas publicitárias ou estatísticas a guardar. Se forem acrescentadas ferramentas desse tipo, a sua ativação terá de ser precedida de uma escolha adequada. Também pode consultar e eliminar os dados deste site nas definições do seu navegador. Para qualquer questão: hernandezfsantos@gmail.com."]}, "fr": {"tag": "Freelance · FR / PT / ES", "nav": ["Mes services", "Les étapes", "À propos"], "talk": "Me contacter", "hero": "Support client en espagnol et en portugais", "intro": "Je suis Romina, votre interlocutrice dédiée à la relation client.", "cta": "Me contacter", "problemTitle": "Quand la langue crée de la distance.", "problem": "De nombreuses relations commerciales passent par un anglais qui n’est la langue maternelle d’aucune des parties. Des nuances se perdent, le ton peut sembler froid et le client ressent de la distance. Les renouvellements peuvent en pâtir.", "what": "Mes services", "tasks": ["Je communique avec vos clients importants dans leur langue maternelle, au nom de votre marque.", "Je suis chaque compte de près : demandes, relances et renouvellements.", "Je prépare les réunions et négociations, avec un briefing culturel pour votre équipe.", "J’adapte les textes et propositions au ton de chaque client.", "Je vous remets un rapport mensuel : situation de chaque compte, risques et prochaines actions."], "who": "Pour qui ?", "yes": "Pour vous si", "yesText": "Vous avez des clients lusophones ou hispanophones et recherchez une interlocutrice dédiée aux échanges et au suivi de leurs demandes.", "no": "Pas adapté si", "noText": "Vous recherchez un centre d’appels, de la prospection commerciale ou une traduction assermentée.", "how": "On commence simplement", "steps": ["On échange pendant 15 minutes pour faire le point sur vos clients et vos besoins.", "On définit ensemble les langues, les canaux et la fréquence du suivi.", "Je prends le relais et vous adresse un récapitulatif des actions menées et des points à améliorer."], "offersTitle": "Trois façons de commencer", "quote": "Sur devis", "offers": [["Mission découverte", "Offre de lancement", "En 2 heures, je relis vos messages automatiques en portugais ou en espagnol. Je vous remets les versions corrigées et les points de vigilance. Ce tarif de lancement s’applique aux 3 premières missions. Tarif habituel : 60 €.", "30 €", "2 h", ""], ["Pack suivi", "Accompagnement mensuel", "Gestion des e-mails, traitement des réclamations et fidélisation en portugais et en espagnol.", "300 €", "10 h/mois", ""], ["Sur mesure", "Selon vos besoins", "Pour plus d’heures ou de canaux de communication, je vous propose un devis personnalisé.", "Sur devis", "", ""]], "offerCta": "Parler de cette offre", "work": "Les outils que j’utilise", "principles": ["Toujours la même interlocutrice responsable.", "Un nombre limité de comptes en parallèle.", "Confidentialité et traitement des données convenus par écrit, conformément au RGPD.", "L’IA peut aider à rédiger un brouillon, dans le respect des règles de confidentialité convenues. Je relis et assume chaque message."], "about": "Moi, c’est Romina.", "bio": "Mon parcours entre le Portugal, le Venezuela et la France m’a appris à prêter attention aux nuances, aux attentes et aux façons de communiquer. Avec onebyonecx, je mets cette expérience au service de vos relations avec vos clients à l’international.", "career": "Diplômée en sciences de la communication et en publicité, j’ai créé onebyonecx pour réunir langues, communication interculturelle et suivi client. Je suis votre interlocutrice et celle de vos partenaires.", "variants": "Je travaille en français, en portugais et en espagnol. Avant de commencer, nous convenons des variantes linguistiques, du ton et des canaux à utiliser. Je coordonne le suivi et vous rends compte en français. Portugaise, vénézuélienne de cœur et installée à Paris, je connais ces cultures de l’intérieur.", "example": "La même intention. Plus de proximité.", "illustrative": "Exemple illustratif · aucun cas client", "before": "E-mail initial en anglais", "after": "Version adaptée en espagnol", "explain": "La version adaptée contextualise la demande, invite aux questions et propose une prochaine étape. Le ton dépend de la personne, de la relation et du contexte, pas seulement du pays.", "faq": "Vos questions sur le suivi client externalisé", "faqs": [["À qui s’adresse ce service de relation client externalisée ?", "Aux TPE, aux PME et aux indépendants qui ont besoin de communiquer avec leurs clients en portugais ou en espagnol. J’accompagne vos clients actuels en assurant le suivi de leurs demandes, de leurs devis et de leurs échanges après-vente. Nous définissons ensemble les clients et les tâches à prendre en charge."], ["Puis-je déléguer le suivi client quelques heures par mois ?", "Oui. La mission découverte comprend 2 heures à 30 € au total pour les 3 premières missions, au lieu de 60 €. Le Pack suivi comprend 10 heures par mois à 300 €. Pour plus d’heures ou plusieurs canaux, un devis est établi avant de commencer."], ["S’agit-il d’une assistante virtuelle ou d’un centre d’appels ?", "À distance, je réalise des tâches d’assistance virtuelle liées à vos clients : e-mails, messages, suivi des demandes et mise à jour des informations. Je reste votre interlocutrice externe dédiée, avec des horaires et un volume de travail convenus ensemble. Je ne propose ni centre d’appels ni prospection commerciale."], ["Pouvez-vous accompagner des clients ou un groupe sur place ?", "Oui, selon mes disponibilités. Je facilite l’accueil et les échanges pratiques en portugais ou en espagnol entre vos clients et votre équipe. Nous convenons du lieu, de la durée, du nombre de participants et des modalités de déplacement avant la mission. Il ne s’agit ni d’interprétariat médical ni de traduction assermentée."], ["Pouvez-vous relancer un devis en portugais ou en espagnol ?", "Oui. Je vérifie que le client a reçu le devis, recueille ses questions et consulte votre équipe avant de communiquer un prix, un délai ou un engagement. Je consigne l’état des échanges et la prochaine étape."], ["Qui valide les décisions et protège les données des clients ?", "Nous définissons par écrit les accès, la confidentialité et les règles de validation. Les prix et les engagements commerciaux restent sous votre contrôle. Toute utilisation de l’IA respecte les conditions convenues et fait l’objet d’une relecture humaine."]], "contact": "Me contacter", "contactIntro": "Vous avez une question ou un besoin de suivi client ?", "fields": ["Nom", "Entreprise", "E-mail professionnel", "Marché ou langue prioritaire", "Quel accompagnement souhaitez-vous : à distance ou sur place ?"], "send": "Ouvrir dans ma messagerie", "missing": "Ce formulaire prépare un e-mail pour Romina. Confirmez l’envoi dans votre messagerie. Le site ne transmet ni ne conserve les données du formulaire.", "email": "hernandezfsantos@gmail.com", "required": "Les champs marqués d’un astérisque (*) sont obligatoires. N’indiquez aucune donnée confidentielle sur vos clients.", "privacy": "Confidentialité", "legal": "Mentions légales", "draft": "Informations à compléter avant l’ouverture au public.", "legalBody": ["Responsable : Romina Hernandez · onebyonecx. Identité légale complète et statut de l’activité : à confirmer.", "Contact : hernandezfsantos@gmail.com · WhatsApp : +33 7 81 66 32 25. Adresse professionnelle et immatriculation (SIREN/RCS, si applicable) : à confirmer.", "Numéro de TVA, si applicable, et responsable de publication : à confirmer.", "Identité, adresse et téléphone de l’hébergeur : à confirmer."], "privacyBody": ["Vous pouvez contacter Romina par e-mail ou sur WhatsApp. Le formulaire prépare uniquement un message dans votre messagerie : vous devez y confirmer l’envoi. Le site ne transmet ni ne conserve le contenu du formulaire.", "En envoyant un e-mail ou en ouvrant WhatsApp, vous utilisez des services externes soumis à leurs propres politiques de confidentialité. Aucun widget de discussion, outil de mesure d’audience ou service publicitaire n’a été intégré.", "Seront également précisés les moyens d’exercer les droits d’accès, rectification, effacement, limitation, opposition et portabilité, selon leur applicabilité, et de saisir la CNIL.", "L’hébergement et le contrôle d’accès peuvent traiter des données techniques selon les règles de leur prestataire ; ces détails restent à confirmer."], "back": "Revenir à l’accueil", "pause": "Mettre la vidéo en pause", "play": "Lire la vidéo", "select": "Langue", "option": "Offre souhaitée", "sector": "Vous exportez ou développez des relations à l’international, sans équipe interne pour en assurer le suivi linguistique et culturel ? Je prends le relais, en lien avec votre équipe.", "tourServices": [["Des demandes traitées, des clients rassurés.", "Je gère vos e-mails et réponds aux demandes de vos clients en portugais et en espagnol.", ""], ["Des réclamations prises en charge.", "J’écoute vos clients, leur réponds et assure le suivi de chaque réclamation pour aider à la résoudre.", ""], ["Des clients qui restent.", "Un suivi régulier, des relances personnalisées et des retours de vos clients pour améliorer votre service.", ""]], "journey": "Comprendre. Adapter. Créer du lien. Entretenir la relation.", "stages": [["Comprendre", "Vos offres, vos valeurs et les attentes de vos interlocuteurs : je commence par connaître le contexte."], ["Adapter", "Le ton, le vocabulaire et les explications s’ajustent à la personne et au marché."], ["Créer du lien", "Devis, questions et réunions : chaque échange a une réponse et une prochaine étape."], ["Entretenir la relation", "Après-vente, retours et contacts réguliers pour garder le dialogue ouvert."]], "cultureTitle": "C’est ici que commence une relation de confiance.", "cultureText": "La confiance se construit dans la façon d’écouter, d’expliquer et de donner suite. Je représente votre entreprise avec une communication claire et proche, pour que vos partenaires se sentent compris et sachent à quoi s’attendre.", "scope": "Une extension de votre équipe.", "scopeText": "Pour les TPE, PME et indépendants qui souhaitent externaliser une partie de leur relation client en portugais et en espagnol : e-mails, demandes, relances et suivi après-vente.", "scopeNote": "Vous gardez la décision commerciale : prix, engagements, conditions et modifications restent soumis à vos règles. Réunions et événements sur place selon disponibilité et devis.", "offerTitle": "Tarifs", "offerNote": "Le nombre d’heures, les canaux de communication et les éventuels frais de déplacement sont précisés dans le devis avant le début de la mission.", "fit": "Brésil · Portugal · Espagne · Amérique latine", "brandLine": "Des échanges clairs. Un suivi attentif. Des relations soignées.", "seoTitle": "Support client externalisé en espagnol et en portugais | onebyonecx", "seoDescription": "Support client en espagnol et en portugais pour les plateformes et les PME : gestion des e-mails, traitement des réclamations et fidélisation.", "identity": "Trois langues, une personne", "proof": "Vos échanges sont suivis, vos décisions restent entre vos mains.", "trustTitle": "Un suivi proche. Un cadre clair.", "trusts": [["Une interlocutrice dédiée", "Romina suit vos échanges et apprend à connaître votre entreprise, vos offres et vos partenaires."], ["Un périmètre convenu", "Tâches, langues, canaux, volume, horaires et délais de réponse sont définis ensemble."], ["Vos décisions, vos règles", "Prix, conditions et engagements restent sous votre contrôle. Je transmets ce qui nécessite votre validation."], ["Un travail visible", "Un rapport mensuel présente les contacts suivis, les blocages et les prochaines actions."]], "trustNote": "Une seule interlocutrice. Périmètre, horaires, accès et confidentialité convenus par écrit. Les prix et engagements commerciaux restent soumis à votre accord.", "blogTitle": "Conseils pour mieux suivre vos clients", "blogIntro": "Des conseils pratiques sur la relance de devis, le suivi client et la communication interculturelle en portugais et en espagnol.", "read": "Lire les conseils", "backHome": "Accueil", "blogPosts": [["Comment relancer un devis par e-mail ?", "Un message clair rappelle le contexte et propose une prochaine étape.", ["Rappelez le devis concerné et vérifiez que votre client l’a reçu.", "Posez une question précise : reste-t-il un point à clarifier sur les prestations, les délais ou les conditions ?", "Convenez du prochain échange. Une absence de réponse ne suffit pas à conclure à un désintérêt."]], ["Communication interculturelle : adapter le ton au client", "La culture donne des pistes ; la personne et le contexte guident les échanges.", ["Observez la façon dont votre interlocuteur s’adresse à vous et le canal qu’il préfère.", "Confirmez le degré de formalité souhaité sans le déduire uniquement de la nationalité de votre interlocuteur.", "Conservez les faits et les engagements dans chaque langue. Adaptez le vocabulaire et les explications pour faciliter la compréhension."]], ["Comment organiser le suivi de vos clients ?", "Un tableau partagé aide votre équipe à suivre les demandes en attente.", ["Notez le sujet, la date du dernier échange et la personne responsable.", "Distinguez la question à résoudre, la décision nécessaire et la prochaine date de contact.", "Séparez les faits confirmés des interprétations et recommandations dans le compte rendu de suivi."]]], "serviceCta": "Parler de ce besoin", "videoLine": "Nous parlons leur langue. Nous comprenons leur culture.", "menuLabel": "Menu", "menuClose": "Fermer le menu", "discover": "Voir mes services", "caseLabel": "Une situation concrète · exemple fictif", "caseTitle": "Comment relancer un devis en espagnol ?", "caseIntro": "Un distributeur au Mexique a demandé un devis à votre entreprise française. Une semaine plus tard, vous attendez toujours sa réponse.", "caseSteps": [["Je reprends contact", "Je vérifie qu’il a reçu le devis et lui demande ce qui reste à préciser, en espagnol."], ["Je consulte votre équipe", "Si la question porte sur un prix ou un délai, je recueille votre réponse avant de prendre un engagement."], ["Je poursuis le suivi", "Je transmets la réponse, conviens du prochain échange et consigne l’état de l’opportunité."]], "caseMessage": "Hola, María. Le escribo para dar seguimiento al presupuesto que le enviamos la semana pasada. ¿Le gustaría aclarar algún punto sobre los plazos o las condiciones? Puedo confirmar los detalles con nuestro equipo.", "messageLabel": "Exemple de message en espagnol", "caseNote": "La communication interculturelle aide à adapter l’approche et le ton à la personne et à la relation. Le suivi tient compte du contexte, sans recette par nationalité.", "toolNav": "Atelier culturel", "clientFollowup": {"title": "Mes outils et ma façon de travailler", "rows": [["Communication", "E-mail, WhatsApp, téléphone et visioconférence."], ["Organisation", "Historique des échanges, tableau de suivi partagé et outils de votre entreprise, selon le périmètre convenu."], ["Compte rendu", "Actions réalisées, demandes en attente et décisions à valider. Rythme défini ensemble."], ["Déplacements", "Lieu, durée, nombre de participants et frais de déplacement convenus avant la mission."]]}, "servicesIntro": "Gestion des e-mails, suivi de votre portefeuille clients et accompagnement multilingue sur place, en lien avec votre équipe.", "workshopToggle": "Traduction et adaptation culturelle de messages", "personalLabel": "Chargée de relation client freelance · FR / PT / ES", "personalQuote": "J’ai appris que les gens oublieront ce que vous avez dit, oublieront ce que vous avez fait, mais n’oublieront jamais ce que vous leur avez fait ressentir.", "launchRate": "", "blogMetaTitle": "Suivi client et relance de devis : conseils | onebyonecx", "blogMetaDescription": "Comment relancer un devis, adapter un e-mail et organiser le suivi client en portugais et en espagnol. Conseils pratiques pour les TPE et PME.", "videoTitle": "Support client en <em>espagnol et en portugais</em>", "videoPromise": "Des échanges plus clairs, dans la langue de vos clients et dans le respect de leurs codes culturels.", "videoLabel": "À distance et sur place", "videoCta": "Me contacter", "whatsappCta": "Parler à Romina sur WhatsApp", "whatsappMessage": "Bonjour Romina, j’ai découvert onebyonecx et je souhaiterais en savoir plus sur votre accompagnement client.", "contactAvailability": "Envoyez-moi un message par e-mail ou sur WhatsApp. Je vous répondrai dès que possible.", "emailCta": "Écrire un e-mail", "mailSubject": "Prise de contact — onebyonecx", "mailStatus": "Confirmez l’envoi dans votre messagerie. Si elle ne s’ouvre pas, utilisez l’adresse e-mail indiquée ci-dessus.", "privacyContact": "Vous pouvez contacter Romina par e-mail ou sur WhatsApp. Le formulaire prépare uniquement un message dans votre messagerie : vous devez y confirmer l’envoi. Le site ne transmet ni ne conserve le contenu du formulaire.", "privacyProvider": "En envoyant un e-mail ou en ouvrant WhatsApp, vous utilisez des services externes soumis à leurs propres politiques de confidentialité. Aucun widget de discussion, outil de mesure d’audience ou service publicitaire n’a été intégré.", "legalContact": "Contact : hernandezfsantos@gmail.com · WhatsApp : +33 7 81 66 32 25. Adresse professionnelle et immatriculation (SIREN/RCS, si applicable) : à confirmer.", "messageLang": "es", "situations": {"eyebrow": "Dans quelles situations faire appel à moi ?", "title": "Vous vous reconnaissez ?", "intro": "Des exemples de ce que je peux prendre en charge pour votre entreprise.", "illustrative": "Exemples fictifs, présentés à titre indicatif.", "scenarioLabel": "Votre situation", "actionLabel": "Ce que je peux faire", "prev": "Exemple précédent", "next": "Exemple suivant", "choose": "Me contacter à ce sujet", "swipe": "Faites défiler les cartes pour découvrir les exemples", "request": "Je souhaite en savoir plus sur cet accompagnement : ", "items": [{"title": "Votre IA répond, mais le client ne se sent pas compris.", "action": "Je relis vos messages automatiques en portugais et en espagnol pour clarifier la réponse, adapter le ton et repérer les promesses que votre équipe ne peut pas confirmer.", "category": "", "scenario": "", "steps": "", "note": "", "revision": {"title": "Exemple de révision en espagnol", "beforeLabel": "Message automatique", "afterLabel": "Après révision", "before": "Su pedido está en proceso. Espere una actualización.", "after": "Lamento el retraso en la entrega de su pedido. Voy a comprobar qué ha pasado con el envío y le escribiré en cuanto tenga más información.", "reason": "J’ai reconnu le retard et précisé la prochaine étape, sans promettre un délai que l’équipe n’a pas confirmé.", "language": "es"}}, {"title": "Vos réponses sont traduites, mais pas adaptées.", "action": "Un message correct en français peut sembler froid en portugais ou en espagnol. J’adapte le ton, pas seulement les mots.", "category": "", "scenario": "", "steps": "", "note": ""}, {"title": "Vos clients écrivent… et attendent.", "action": "Je gère les e-mails et les demandes de vos clients pour que chacun reçoive une réponse claire et personnalisée.", "category": "", "scenario": "", "steps": "", "note": ""}]}, "audienceTitle": "Pour qui ?", "audience": "Pour les plateformes et les services en ligne qui comptent des clients lusophones ou hispanophones : formation en ligne, fintech, santé numérique ou logiciels en ligne (SaaS). Vous pouvez déléguer une partie du suivi sans recruter à temps plein ni faire appel à un centre d’appels.", "onsite": "Accompagnement sur place ou en visioconférence, sur demande.", "illustratedTitle": "Accompagnement sur place en portugais et en espagnol", "illustrated": "Je me déplace sur demande pour accueillir vos clients ou vos groupes qui ne sont pas à l’aise en français. Je les oriente, réponds à leurs questions pratiques et facilite les échanges avec votre équipe en portugais ou en espagnol, de leur arrivée à la fin du rendez-vous. Ce service s’adresse, par exemple, à un établissement qui accueille des étudiants tout juste arrivés en France ou à un institut de beauté qui reçoit plusieurs clients lusophones ou hispanophones le même jour. Nous convenons à l’avance du lieu, de la date et du nombre de personnes à accompagner.", "workingCopy": ["Je m’adapte aux outils de votre équipe pour répondre à vos clients et suivre leurs demandes, qu’il s’agisse de votre messagerie électronique, de WhatsApp Business, de votre outil de chat ou de votre CRM.", "Selon vos besoins, je peux aussi créer ou mettre en page sur Canva des présentations de vos services, des guides de bienvenue ou des fiches pratiques, en respectant votre identité visuelle."], "closeTitle": "Un client bien compris est un client qui reste.", "closeCopy": "Parlons de vos clients lusophones et hispanophones.", "bioExtra": "Portugaise, vénézuélienne de cœur, installée à Paris : je connais ces cultures de l’intérieur.", "cookies": "Cookies", "cookiesTitle": "Cookies et stockage local", "cookiesBody": ["Le code de onebyonecx n’installe aucun cookie publicitaire ni traceur de mesure d’audience. Aucun outil Google Analytics, pixel Meta ou module de suivi des réseaux sociaux n’est intégré.", "Les photographies, le fichier vidéo et les polices sont hébergés avec le site. La vidéo n’est pas un lecteur YouTube ou Vimeo intégré. Le choix de langue repose sur l’adresse de la page et ne crée pas de cookie de préférence.", "Le stockage de session « onebyone-review-brief » sert uniquement à transférer un récapitulatif de l’Atelier vers le formulaire de contact lorsque vous demandez une révision humaine. Il contient le récapitulatif préparé, reste dans votre navigateur et est supprimé après son insertion dans le formulaire, ou à la fin de la session de l’onglet. L’analyse par IA étant actuellement désactivée, aucun résultat automatique n’est généré.", "Les liens e-mail et WhatsApp ouvrent des services externes uniquement lorsque vous les utilisez. Ces services appliquent leurs propres règles de confidentialité et de cookies. Aucun widget WhatsApp tiers n’est chargé dans la page.", "La plateforme d’hébergement et de contrôle d’accès peut utiliser des mécanismes techniques pour la sécurité et l’authentification. Ils sont gérés par cette plateforme, indépendamment du code du site. Leurs noms et durées ne sont pas définis par onebyonecx.", "Aucun cookie facultatif n’est proposé dans cette version : il n’y a donc pas de choix publicitaire ou statistique à enregistrer. Si de tels outils sont ajoutés, leur activation devra être précédée d’un choix adapté. Vous pouvez également consulter et supprimer les données de ce site dans les paramètres de votre navigateur. Pour toute question : hernandezfsantos@gmail.com."]}, "es": {"tag": "Freelance · FR / PT / ES", "nav": ["Servicios", "Cómo funciona", "Sobre mí"], "talk": "Contactar", "hero": "Atención al cliente y seguimiento posventa en francés y portugués", "intro": "Ayudo a empresas a responder a sus clientes, gestionar incidencias y dar seguimiento a cada solicitud después de la compra.", "cta": "Contactar", "problemTitle": "Cuando el idioma crea distancia.", "problem": "Muchas relaciones comerciales se desarrollan en un inglés que no es la lengua materna de ninguna de las partes. Se pierden matices, el tono puede parecer frío y el cliente siente distancia. Esto puede poner en riesgo las renovaciones.", "what": "Mis servicios", "tasks": ["Me comunico con sus clientes importantes en su lengua materna, en nombre de su marca.", "Acompaño cada cuenta de cerca: solicitudes, seguimiento y renovaciones.", "Preparo reuniones y negociaciones, con un informe cultural para su equipo.", "Adapto textos y propuestas al tono de cada cliente.", "Le entrego un informe mensual: estado de cada cuenta, riesgos y próximas acciones."], "who": "Para quién es", "yes": "Es para usted si", "yesText": "Tiene clientes de habla francesa o portuguesa y busca una persona dedicada a la comunicación y al seguimiento de sus solicitudes.", "no": "No es para usted si", "noText": "Busca atención masiva, prospección comercial o traducción certificada.", "how": "Empezamos de forma sencilla", "steps": ["Conversamos durante 15 minutos sobre sus clientes y sus necesidades.", "Acordamos los idiomas, los canales y la frecuencia del seguimiento.", "Me encargo del seguimiento y le envío un resumen de las gestiones realizadas y de lo que queda por mejorar."], "offersTitle": "Formas de empezar", "quote": "Presupuesto personalizado", "offers": [["Primera colaboración", "Oferta de lanzamiento", "En 2 horas reviso sus mensajes automáticos en portugués o francés. Le entrego las versiones corregidas y le indico qué aspectos requieren atención. Esta tarifa de lanzamiento se aplica a las 3 primeras colaboraciones. Tarifa habitual: 60 €.", "30 €", "2 h", ""], ["Plan de seguimiento", "Seguimiento mensual", "Gestión de correos electrónicos, atención de reclamaciones y fidelización en portugués y francés.", "300 €", "10 h/mes", ""], ["A medida", "Según sus necesidades", "Si necesita más horas o varios canales de comunicación, le preparo un presupuesto a medida.", "Presupuesto a medida", "", ""]], "offerCta": "Hablar de esta opción", "work": "Las herramientas que utilizo", "principles": ["Siempre la misma persona responsable.", "Pocas cuentas al mismo tiempo.", "Confidencialidad y tratamiento de datos acordados por escrito, conforme al RGPD.", "Uso IA como apoyo para borradores, respetando las reglas de confidencialidad acordadas. Reviso y asumo la responsabilidad de cada mensaje."], "about": "Soy Romina.", "bio": "Mi experiencia en Portugal, Venezuela y Francia me ha enseñado a prestar atención a los matices, las expectativas y las distintas formas de comunicarse. En onebyonecx, pongo esa experiencia al servicio de su relación con clientes de otros mercados.", "career": "Con formación en Ciencias de la Comunicación y Publicidad, creé onebyonecx para reunir idiomas, comunicación intercultural y seguimiento de clientes. Soy la interlocutora de su empresa y de sus colaboradores.", "variants": "Trabajo en francés, portugués y español. Antes de empezar, acordamos las variantes lingüísticas, el tono y los canales de comunicación. Coordino el trabajo y le envío los informes en francés. Soy portuguesa, venezolana de corazón y vivo en París. Conozco estas culturas desde dentro.", "example": "La misma intención. Más cercanía.", "illustrative": "Ejemplo ilustrativo · no es un caso de cliente", "before": "Correo electrónico inicial en inglés", "after": "Versión adaptada en español", "explain": "La versión adaptada contextualiza la solicitud, invita a plantear dudas y propone un siguiente paso. El tono depende de la persona, la relación y el contexto, no solo del país.", "faq": "Preguntas sobre la atención y el seguimiento de clientes", "faqs": [["¿A quién se dirige este servicio de atención al cliente externalizada?", "A microempresas, pymes y profesionales independientes que necesitan comunicarse con sus clientes en portugués o francés. Me encargo del seguimiento de relaciones existentes, solicitudes, presupuestos y consultas de posventa. Definimos juntos los clientes y las tareas que voy a atender."], ["¿Puedo contratar apoyo al cliente durante unas pocas horas al mes?", "Sí. La primera colaboración incluye 2 horas por un total de 30 €, en lugar de 60 €. Esta oferta está limitada a las 3 primeras colaboraciones. El Plan de seguimiento incluye 10 horas al mes por 300 €. Para más horas o varios canales, preparo un presupuesto antes de empezar."], ["¿Es un servicio de asistente virtual o de centro de llamadas?", "A distancia, realizo tareas de asistencia virtual relacionadas con sus clientes: correos electrónicos, mensajes, seguimiento de solicitudes y actualización de información. Soy su interlocutora externa dedicada, con horarios y un volumen de trabajo acordados. No ofrezco servicios de centro de llamadas ni de prospección comercial."], ["¿Puede acompañar a clientes o a un grupo de forma presencial?", "Sí, según disponibilidad. Ayudo a recibir a sus clientes y facilito la comunicación en portugués o francés con su equipo. El lugar, la duración, el número de participantes y el desplazamiento se acuerdan antes del servicio. No se trata de interpretación médica ni de traducción jurada."], ["¿Puede dar seguimiento a un presupuesto en portugués o francés?", "Sí. Confirmo que el cliente ha recibido el presupuesto, recojo sus preguntas y consulto con su equipo antes de comunicar un precio, un plazo o un compromiso. Registro el estado de la conversación y el siguiente paso."], ["¿Quién aprueba las decisiones y protege los datos de los clientes?", "Definimos por escrito los accesos, la confidencialidad y las reglas de aprobación. Los precios y los compromisos comerciales siguen bajo su control. Cualquier uso de IA respeta las condiciones acordadas e incluye revisión humana."]], "contact": "Contactar", "contactIntro": "¿Tiene alguna pregunta o necesita ayuda con la atención a sus clientes?", "fields": ["Nombre", "Empresa", "Correo electrónico profesional", "Mercado o idioma prioritario", "¿Qué tipo de apoyo necesita, a distancia o presencial?"], "send": "Abrir en mi aplicación de correo", "missing": "Este formulario prepara un correo electrónico para Romina. Confirme el envío en su aplicación de correo. El sitio no transmite ni guarda los datos del formulario.", "email": "hernandezfsantos@gmail.com", "required": "Los campos marcados con un asterisco (*) son obligatorios. No incluya datos confidenciales de sus clientes.", "privacy": "Privacidad", "legal": "Aviso legal", "draft": "Información por completar antes de abrir al público.", "legalBody": ["Responsable: Romina Hernandez · onebyonecx. Identidad legal completa y situación de la actividad: por confirmar.", "Contacto: hernandezfsantos@gmail.com · WhatsApp: +33 7 81 66 32 25. Dirección profesional e inscripción (SIREN/RCS, si corresponde): por confirmar.", "Número de IVA, si corresponde, y responsable de publicación: por confirmar.", "Identidad, dirección y teléfono del proveedor de alojamiento: por confirmar."], "privacyBody": ["Puede contactar con Romina por correo electrónico o WhatsApp. El formulario solo prepara un mensaje en su aplicación de correo: debe confirmar allí el envío. El sitio no transmite ni guarda el contenido del formulario.", "Al enviar un correo electrónico o abrir WhatsApp, utiliza servicios externos sujetos a sus propias políticas de privacidad. No se ha integrado ningún widget de chat, herramienta de analítica ni servicio publicitario.", "También se indicará cómo ejercer los derechos de acceso, rectificación, supresión, limitación, oposición y portabilidad, cuando proceda, y reclamar ante la CNIL.", "El alojamiento y el control de acceso pueden tratar datos técnicos según las reglas de su proveedor; estos detalles deben confirmarse."], "back": "Volver al inicio", "pause": "Pausar vídeo", "play": "Reproducir vídeo", "select": "Idioma", "option": "Opción de interés", "sector": "¿Necesita dar seguimiento a clientes en francés o portugués, pero no cuenta con una persona dedicada a esa comunicación? Trabajo en coordinación con su equipo.", "tourServices": [["Solicitudes atendidas, clientes más tranquilos.", "Gestiono el correo electrónico y respondo a las solicitudes de sus clientes en portugués y francés.", ""], ["Atención y seguimiento de reclamaciones.", "Escucho a sus clientes, les respondo y hago un seguimiento de cada caso para ayudar a resolverlo.", ""], ["Clientes que se quedan.", "Seguimiento periódico, contactos personalizados y opiniones de sus clientes para mejorar el servicio.", ""]], "journey": "Comprender. Adaptar. Crear conexión. Cuidar la relación.", "stages": [["Comprender", "Sus servicios, valores y las expectativas de sus interlocutores: empiezo por conocer el contexto."], ["Adaptar", "El tono, el vocabulario y las explicaciones se ajustan a la persona y al mercado."], ["Crear conexión", "Propuestas, dudas y reuniones: cada contacto recibe respuesta y un siguiente paso."], ["Cuidar la relación", "Posventa, comentarios y contactos regulares para mantener el diálogo abierto."]], "cultureTitle": "Aquí empieza una relación de confianza.", "cultureText": "La confianza se construye al escuchar, explicar y dar seguimiento. Represento a su empresa con una comunicación clara y cercana, para que sus socios se sientan comprendidos y sepan qué esperar.", "scope": "Una extensión de su equipo.", "scopeText": "Para pequeñas empresas y profesionales que necesitan delegar la atención al cliente, la gestión de mensajes y el seguimiento de relaciones en francés y portugués.", "scopeNote": "Usted mantiene la decisión comercial: precios, compromisos, condiciones y cambios siguen sus reglas. Reuniones y eventos presenciales según disponibilidad y presupuesto.", "offerTitle": "Tarifas", "offerNote": "El número de horas, los canales de comunicación y los posibles gastos de desplazamiento se detallan en el presupuesto antes de empezar.", "fit": "Francia · Portugal · Brasil", "brandLine": "Comunicación clara. Seguimiento cercano. Relaciones cuidadas.", "seoTitle": "Atención al cliente y seguimiento posventa en francés y portugués | onebyonecx", "seoDescription": "Atención al cliente y seguimiento posventa en francés y portugués para empresas. Respuestas a clientes, gestión de incidencias y seguimiento de solicitudes.", "identity": "Tres idiomas, una persona", "proof": "Sus contactos reciben seguimiento. Las decisiones siguen en sus manos.", "trustTitle": "Seguimiento cercano. Reglas claras.", "trusts": [["Una interlocutora dedicada", "Romina sigue los contactos y conoce su empresa, sus ofertas y sus socios."], ["Un alcance acordado", "Definimos juntos tareas, idiomas, canales, volumen, horarios y plazos de respuesta."], ["Usted mantiene las decisiones", "Precios, condiciones y compromisos siguen bajo su control. Derivo lo que necesita su aprobación."], ["Trabajo visible", "Un informe mensual presenta los contactos atendidos, los bloqueos y las próximas acciones."]], "trustNote": "Una sola interlocutora. Alcance, horarios, accesos y confidencialidad acordados por escrito. Los precios y compromisos comerciales siguen sujetos a su aprobación.", "blogTitle": "Consejos para comunicarse con sus clientes", "blogIntro": "Ideas prácticas sobre atención al cliente, seguimiento de propuestas y comunicación intercultural en portugués y francés.", "read": "Leer los consejos", "backHome": "Inicio", "blogPosts": [["Cómo dar seguimiento a una propuesta por correo electrónico", "Un mensaje claro recuerda el contexto y propone un próximo paso.", ["Identifique el presupuesto o la propuesta y confirme si el cliente lo recibió.", "Plantee una pregunta concreta: ¿falta aclarar el alcance, los plazos o las condiciones?", "Acuerde el próximo contacto. La falta de respuesta, por sí sola, no indica falta de interés."]], ["Comunicación intercultural: cómo adaptar el tono al cliente", "La cultura ofrece pistas; la persona y el contexto orientan la comunicación.", ["Observe cómo se dirige a usted su interlocutor y qué canal prefiere.", "Confirme sus expectativas de formalidad, sin deducirlas únicamente de su nacionalidad.", "Mantenga los hechos y compromisos en todos los idiomas. Adapte el vocabulario y las explicaciones para facilitar la comprensión."]], ["Cómo organizar el seguimiento de clientes", "Un registro compartido ayuda al equipo a atender las solicitudes pendientes.", ["Anote el asunto, la fecha del último contacto y la persona responsable.", "Distinga la duda pendiente, la decisión necesaria y la próxima fecha de contacto.", "Separe los hechos confirmados de las interpretaciones y recomendaciones en el informe de seguimiento."]]], "serviceCta": "Hablar de este apoyo", "videoLine": "Hablamos su idioma. Comprendemos su cultura.", "menuLabel": "Menú", "menuClose": "Cerrar menú", "discover": "Ver mis servicios", "caseLabel": "Una situación cotidiana · ejemplo ficticio", "caseTitle": "¿Cómo dar seguimiento a una propuesta en portugués?", "caseIntro": "Un distribuidor de Brasil solicitó un presupuesto a su empresa. Pasó una semana y todavía no respondió.", "caseSteps": [["Retomo el contacto", "Confirmo si recibió la propuesta y pregunto qué necesita aclarar, en portugués."], ["Consulto con su equipo", "Si la consulta trata sobre un precio o un plazo, reúno la respuesta antes de asumir un compromiso."], ["Continúo el seguimiento", "Transmito la respuesta, acuerdo el próximo contacto y registro el estado de la conversación."]], "caseMessage": "Olá, María. Escrevo para saber se recebeu a proposta que enviamos na semana passada. Gostaria de esclarecer algum ponto sobre os prazos ou as condições? Posso confirmar os detalhes com a equipe.", "messageLabel": "Ejemplo de mensaje en portugués", "caseNote": "La comunicación intercultural ayuda a adaptar la forma de dirigirse al cliente y el tono a la persona y a la relación. El seguimiento tiene en cuenta el contexto, sin fórmulas por nacionalidad.", "toolNav": "Taller cultural", "clientFollowup": {"title": "Mis herramientas y mi forma de trabajar", "rows": [["Comunicación", "Correo electrónico, WhatsApp, teléfono y videollamada."], ["Organización", "Historial de los contactos, registro de seguimiento compartido y herramientas de su empresa, según el alcance acordado."], ["Informe", "Acciones realizadas, solicitudes pendientes y decisiones por validar. Frecuencia acordada conjuntamente."], ["Desplazamientos", "Lugar, duración, número de participantes y gastos de desplazamiento acordados antes de la colaboración."]]}, "servicesIntro": "Gestión de correos electrónicos, seguimiento de clientes y acompañamiento multilingüe presencial, con una comunicación adaptada a cada relación.", "workshopToggle": "Traducción y adaptación cultural de mensajes", "personalLabel": "Atención al cliente en portugués y francés", "personalQuote": "He aprendido que las personas olvidarán lo que dijiste, olvidarán lo que hiciste, pero nunca olvidarán cómo las hiciste sentir.", "launchRate": "", "blogMetaTitle": "Atención al cliente y seguimiento: consejos | onebyonecx", "blogMetaDescription": "Ideas prácticas sobre atención al cliente, seguimiento de propuestas y comunicación intercultural en portugués y francés.", "videoTitle": "Atención al cliente y seguimiento posventa en <em>francés y portugués</em>", "videoPromise": "Una comunicación más clara, en el idioma de sus clientes y adaptada a su cultura.", "videoLabel": "A distancia y en persona", "videoCta": "Contactar", "whatsappCta": "Hablar con Romina por WhatsApp", "whatsappMessage": "Hola, Romina. He visto onebyonecx y me gustaría saber más sobre su servicio de atención y seguimiento de clientes.", "contactAvailability": "Envíeme un mensaje por correo electrónico o por WhatsApp. Le responderé lo antes posible.", "emailCta": "Escribir un correo electrónico", "mailSubject": "Solicitud de contacto — onebyonecx", "mailStatus": "Confirme el envío en su aplicación de correo. Si no se abre, utilice la dirección indicada arriba.", "privacyContact": "Puede contactar con Romina por correo electrónico o WhatsApp. El formulario solo prepara un mensaje en su aplicación de correo: debe confirmar allí el envío. El sitio no transmite ni guarda el contenido del formulario.", "privacyProvider": "Al enviar un correo electrónico o abrir WhatsApp, utiliza servicios externos sujetos a sus propias políticas de privacidad. No se ha integrado ningún widget de chat, herramienta de analítica ni servicio publicitario.", "legalContact": "Contacto: hernandezfsantos@gmail.com · WhatsApp: +33 7 81 66 32 25. Dirección profesional e inscripción (SIREN/RCS, si corresponde): por confirmar.", "messageLang": "pt-BR", "situations": {"eyebrow": "¿En qué situaciones puede contar conmigo?", "title": "¿Es este su caso?", "intro": "Ejemplos concretos del apoyo que puedo ofrecer a su empresa.", "illustrative": "Ejemplos ficticios que ilustran el servicio.", "scenarioLabel": "Su situación", "actionLabel": "Qué puedo hacer", "prev": "Ejemplo anterior", "next": "Ejemplo siguiente", "choose": "Consultar sobre este servicio", "swipe": "Deslice las tarjetas para descubrir los ejemplos", "request": "Me gustaría saber más sobre este servicio: ", "items": [{"title": "Su IA responde, pero el cliente no se siente comprendido.", "action": "Reviso sus mensajes automáticos en portugués y francés para aclarar la respuesta, adaptar el tono e identificar promesas que su equipo aún no puede confirmar.", "category": "", "scenario": "", "steps": "", "note": "", "revision": {"title": "Ejemplo de revisión en portugués", "beforeLabel": "Mensaje automático", "afterLabel": "Tras la revisión", "before": "O seu pedido está em processamento. Aguarde uma atualização.", "after": "Lamento que a sua encomenda ainda não tenha chegado. Vou confirmar o ponto de situação com a equipa de expedição e volto a contactá-lo assim que tiver novidades.", "reason": "Reconocí el retraso y aclaré el siguiente paso, sin prometer un plazo que aún no se ha confirmado.", "language": "pt-PT"}}, {"title": "Sus respuestas están traducidas, pero no adaptadas.", "action": "Un mensaje correcto en español puede parecer frío en portugués o francés. Adapto el tono, no solo las palabras.", "category": "", "scenario": "", "steps": "", "note": ""}, {"title": "Sus clientes escriben… y esperan.", "action": "Me encargo del buzón de correo y de las solicitudes para que cada cliente reciba una respuesta clara y humana.", "category": "", "scenario": "", "steps": "", "note": ""}]}, "audienceTitle": "¿Para quién?", "audience": "Para plataformas y servicios en línea con clientes que hablan portugués o francés, en ámbitos como la formación en línea, la tecnología financiera, la salud digital o el software como servicio (SaaS). Puede delegar parte de la atención sin contratar a nadie a tiempo completo ni recurrir a un centro de llamadas.", "onsite": "Atención presencial o por videollamada, previa solicitud.", "illustratedTitle": "Cuando un pedido necesita algo más que una traducción", "illustrated": "Un cliente francés te escribe para preguntar por su pedido. Le respondes en inglés y, al leer su respuesta, te queda una duda: ¿quiere cambiar la dirección de entrega o solo confirmar que la que figura en el pedido es correcta? Preparas un borrador en francés con ayuda de la IA, pero quieres que alguien revise la conversación completa y compruebe si la respuesta aclara la duda con el tono adecuado.", "workingCopy": ["Me adapto a las herramientas de su equipo para responder a sus clientes y hacer un seguimiento de sus solicitudes. Trabajo con el correo electrónico, WhatsApp Business, el chat y el CRM.", "Según sus necesidades, también puedo crear o diseñar en Canva presentaciones de sus servicios, guías de bienvenida o fichas prácticas, respetando su identidad visual."], "closeTitle": "Un cliente que se siente comprendido es un cliente que se queda.", "closeCopy": "Hablemos de sus clientes que hablan portugués o francés.", "bioExtra": "Portuguesa, venezolana de corazón y residente en París: conozco estas culturas desde dentro.", "cookies": "Cookies", "cookiesTitle": "Cookies y almacenamiento local", "cookiesBody": ["El código de onebyonecx no instala cookies publicitarias ni herramientas de medición de audiencia. No se han integrado Google Analytics, el píxel de Meta ni módulos de seguimiento de redes sociales.", "Las fotografías, el archivo de vídeo y las fuentes se alojan con el sitio. El vídeo no utiliza un reproductor de YouTube o Vimeo integrado. El idioma se determina mediante la dirección de la página, sin crear una cookie de preferencia.", "El almacenamiento de sesión «onebyone-review-brief» se utiliza únicamente para transferir un resumen del Taller al formulario de contacto cuando solicita una revisión humana. Contiene el resumen preparado, permanece en su navegador y se elimina después de insertarlo en el formulario o al finalizar la sesión de la pestaña. Como el análisis con IA está actualmente desactivado, no se generan resultados automáticos.", "Los enlaces de correo electrónico y WhatsApp solo abren servicios externos cuando los utiliza. Esos servicios aplican sus propias normas de privacidad y cookies. No se carga en la página ningún módulo externo de chat de WhatsApp.", "La plataforma de alojamiento y control de acceso puede utilizar mecanismos técnicos de seguridad y autenticación. Los gestiona la plataforma, independientemente del código del sitio. Sus nombres y plazos de conservación no los define onebyonecx.", "Esta versión no ofrece cookies opcionales, por lo que no hay preferencias publicitarias o estadísticas que guardar. Si se añaden herramientas de este tipo, su activación deberá ir precedida de una elección adecuada. También puede consultar y eliminar los datos de este sitio en la configuración de su navegador. Para cualquier consulta: hernandezfsantos@gmail.com."], "illustratedFollowUp": "Si estas situaciones se repiten, puedo encargarme de atender a tus clientes en francés. Reviso el contexto, les hago las preguntas necesarias para entender qué necesitan y coordino la respuesta con tu equipo. Después, hago el seguimiento hasta que la consulta quede resuelta."}};const LOCALES={pt:'pt-PT',fr:'fr-FR',es:'es'};const exportRoot=new URL('../',document.currentScript.src);const routeLanguage=location.pathname.slice(exportRoot.pathname.length).split('/')[0];const requestedLanguage=new URLSearchParams(location.search).get('lang');const lang=[routeLanguage,requestedLanguage].find(value=>Object.hasOwn(LOCALES,value))||'fr';const ids=['services','process','about'];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const link=(label,id,cls='')=>`<a class="${cls}" href="${exportRoot.href}${lang}/index.html#${id}">${label}</a>`;const sec=(id,title,body,cls='')=>`<section id="${id}" class="section ${cls}"><div class="wrap"><h2>${title}</h2>${body}</div></section>`;const CONTACT_EMAIL='hernandezfsantos@gmail.com';const CONTACT_WHATSAPP='33781663225';function contactMailto(d,values={}){const names=['name','company','email','country','message'];const body=names.map((key,i)=>d.fields[i]+': '+String(values[key]||'').trim()).join('\n\n');return 'mailto:'+CONTACT_EMAIL+'?subject='+encodeURIComponent(d.mailSubject)+'&body='+encodeURIComponent(body)}function whatsappUrl(d){return 'https://wa.me/'+CONTACT_WHATSAPP+'?text='+encodeURIComponent(d.whatsappMessage)}function whatsappIcon(){return '<svg class="whatsapp-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false"><path d="M20.4 11.8a8.4 8.4 0 0 1-12.5 7.3L3 20.5l1.4-4.8a8.4 8.4 0 1 1 16-3.9Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M8.7 7.4c-.2-.5-.4-.5-.7-.5h-.5c-.3 0-.6.2-.8.5-.4.5-.7 1.1-.6 1.8.1 2.4 3.6 6.2 6.5 7 .7.2 1.5.1 2.1-.2.5-.3 1.1-1 1.1-1.4l-.1-.6-2.2-1.1c-.3-.1-.5-.1-.7.2l-.8.9c-.2.2-.4.2-.7.1a7 7 0 0 1-3.2-2.9c-.2-.3-.1-.4.1-.6l.7-.8c.2-.2.2-.4.1-.7l-.8-1.7Z" fill="currentColor"/></svg>'}function floatingWhatsapp(d){return `<a class="whatsapp-floating" href="${whatsappUrl(d)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(d.whatsappCta)}">${whatsappIcon()}<span class="whatsapp-tooltip">${d.whatsappCta}</span></a>`}function menuLinks(d){return `<a href="${exportRoot.href}${lang}/index.html">${d.backHome}</a>${d.nav.map((x,i)=>`<a href="${exportRoot.href}${lang}/index.html#${ids[i]}">${x}</a>`).join('')}<a href="${exportRoot.href}${lang}/blog/index.html" ${location.pathname.includes('/blog')?'aria-current="page"':''}>Blog</a>${link(d.talk,'contact','btn')}`}function languageLinks(d){return `<div class="language-links" aria-label="${d.select}">${['fr','pt','es'].map(x=>`<a href="${exportRoot.href}${x}/${location.pathname.includes('/blog')?'blog/':location.pathname.includes('/outil-communication/')?'outil-communication/':''}index.html" hreflang="${LOCALES[x]}" lang="${LOCALES[x]}" ${x===lang?'aria-current="true"':''}>${x.toUpperCase()}</a>`).join('')}</div>`}
