function animateFoliraEntry(element){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches||!element.animate||!window.OneByOneFramerSpring)return;
 if(element.matches('.profile-card-shell'))return;
 const spring=window.OneByOneFramerSpring({keyframes:[0,1],stiffness:200,damping:30,mass:1,restSpeed:.01,restDelta:.001});
 const frames=[];let duration=0;
 for(let time=0;time<=1800;time+=16){const state=spring.next(time);duration=time;frames.push({opacity:Math.max(.001,Math.min(1,state.value)),transform:'translateY('+(40*(1-state.value))+'px)'});if(time>160&&state.done)break;}
 const delay=Number.parseFloat(element.style.getPropertyValue('--reveal-delay'))||0;
 element.dataset.motionEngine='framer-spring';element.dataset.entryState='animating';const animation=element.animate(frames,{duration:Math.max(320,duration),delay,easing:'linear',fill:'backwards'});animation.finished.then(()=>element.dataset.entryState='complete').catch(()=>element.dataset.entryState='cancelled');
}
let foliraWordObserver,foliraScrollHandler,foliraMotionFrame=0;
function setupFoliraMotion(){
 foliraWordObserver?.disconnect();
 if(foliraScrollHandler){window.removeEventListener('scroll',foliraScrollHandler);window.removeEventListener('resize',foliraScrollHandler);}
 if(foliraMotionFrame)cancelAnimationFrame(foliraMotionFrame);
 foliraMotionFrame=0;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 document.querySelectorAll('.menu-panel a,.btn').forEach(el=>{
  if(el.childElementCount||!el.textContent.trim())return;
  const span=document.createElement('span');span.className='nav-roll';span.textContent=el.textContent;el.replaceChildren(span);
 });
 // Keep French punctuation attached to the preceding word, including with reduced motion.
 document.querySelectorAll('h1,h2,h3').forEach(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;node.textContent=node.textContent.replace(/(\S)[ \t\u00a0\u202f]+([?!;:])/g,'$1\u00a0$2');}});
 if(reduced.matches)return;
 const split=(el,kind)=>{
  if(el.dataset.foliraSplit)return;el.dataset.foliraSplit=kind;if(kind==='letters')el.setAttribute('aria-label',el.textContent);
  const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  let index=0;
  nodes.forEach(node=>{const fragment=document.createDocumentFragment();node.textContent.split(/([ \t\r\n]+)/).forEach(token=>{
   if(!token)return;if(/^\s+$/.test(token)){fragment.append(document.createTextNode(token));return;}
   const outer=document.createElement('span');outer.className=kind==='reading'?'reading-word':'motion-word';if(kind==='letters')outer.setAttribute('aria-hidden','true');
   if(kind==='letters')Array.from(token).forEach(letter=>{const span=document.createElement('span');span.className='hero-letter';span.style.setProperty('--letter-delay',Math.min(index++*12,850)+'ms');span.textContent=letter;outer.append(span);});
   else if(kind==='words'){if(/^(clientes?|clients?|clientèle|acompanhamento|suivi|seguimiento|idiomas|línguas|langues)$/i.test(token.replace(/[.,?!:;]/g,'')))outer.classList.add('heading-accent');const span=document.createElement('span');span.className='motion-word-inner';span.style.setProperty('--word-delay',Math.min(index++*55,385)+'ms');span.textContent=token;outer.append(span);}
   else{outer.textContent=token;outer.dataset.readingIndex=index++;}
   fragment.append(outer);
  });node.replaceWith(fragment);});
 };
 document.querySelectorAll('.video-message h1').forEach(el=>split(el,'letters'));
 const headings=[...document.querySelectorAll('.section h2,.blog-heading h1')];headings.forEach(el=>{split(el,'words');el.classList.add('word-reveal');});
 if('IntersectionObserver' in window){foliraWordObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');foliraWordObserver.unobserve(e.target)}}),{threshold:.15,rootMargin:'0px 0px -35px 0px'});headings.forEach(el=>foliraWordObserver.observe(el));}else headings.forEach(el=>el.classList.add('visible'));
 const statement=document.querySelector('.bio-statement');if(statement)statement.textContent=statement.textContent;
 const words=statement?[...statement.querySelectorAll('.reading-word')]:[];
 const steps=[...document.querySelectorAll('.working-steps li')];
 const update=()=>{foliraMotionFrame=0;if(reduced.matches){words.forEach(word=>word.style.setProperty('--reading-shade','17'));return;}
  if(statement){const rect=statement.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(innerHeight*.88-rect.top)/(innerHeight*.45+rect.height*.4)));words.forEach((word,i)=>{const amount=Math.max(0,Math.min(1,(progress-i/Math.max(1,words.length))*words.length/3));word.style.setProperty('--reading-shade',Math.round(168-151*amount));});}
  const rects=steps.map(step=>step.getBoundingClientRect());
  const followupEntrance=innerWidth<=760?190:290;
  const reveals=rects.map((rect,i)=> {
   const entrance=i===0?Math.max(innerHeight*.8,252):followupEntrance;
   return Math.max(0,Math.min(1,(entrance-rect.top)/72));
  });
  const current=reveals.findLastIndex(reveal=>reveal>=.9);
  steps.forEach((step,i)=>{
   step.classList.toggle('step-current',i===current);
   const gap=rects[i+1]?rects[i+1].top-rects[i].top:Infinity;
   const overlap=Math.max(0,Math.min(1,(step.offsetHeight+32-gap)/Math.max(1,step.offsetHeight)));
   step.style.setProperty('--step-scale',String(1-overlap*.035));
   step.style.setProperty('--step-reveal',String(reveals[i]));
  });
 };
 foliraScrollHandler=()=>{if(!foliraMotionFrame)foliraMotionFrame=requestAnimationFrame(update)};
 window.addEventListener('scroll',foliraScrollHandler,{passive:true});window.addEventListener('resize',foliraScrollHandler,{passive:true});update();
 reduced.addEventListener('change',event=>{if(event.matches){document.querySelectorAll('.word-reveal').forEach(el=>el.classList.add('visible'));words.forEach(word=>word.style.setProperty('--reading-shade','17'));foliraWordObserver?.disconnect();}},{once:true});
}
let revealObserver,sectionObserver,scrollFrame=0,scrollHandler;
function setupMotion(){
setupFoliraMotion();
revealObserver?.disconnect();sectionObserver?.disconnect();
document.querySelector('.scroll-progress')?.remove();
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const refresh=()=>{scrollFrame=0;const total=document.documentElement.scrollHeight-innerHeight;progress.style.transform='scaleX('+Math.max(0,Math.min(1,total>0?scrollY/total:0))+')'};
if(scrollHandler)window.removeEventListener('scroll',scrollHandler);
if(scrollFrame)cancelAnimationFrame(scrollFrame);
scrollFrame=0;
scrollHandler=()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(refresh)};
window.addEventListener('scroll',scrollHandler,{passive:true});refresh();
const targets=[...document.querySelectorAll('.export-hero-copy>*,.section>.wrap>h2,.freelance-intro,.tour-card,.client-followup,.bio>.profile-card-shell,.personal-quote,.example-grid>*,.situations-heading,.situation-card,.situations-bottom,#faq details,#contact .two>*')].filter(el=>el.getClientRects().length>0);
if(!reduce.matches&&'IntersectionObserver' in window){
revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');animateFoliraEntry(e.target);revealObserver.unobserve(e.target)}})},{threshold:.06,rootMargin:'0px 0px -28px 0px'});
targets.forEach((el,i)=>{if(el.getBoundingClientRect().bottom>0){el.classList.add('motion-ready');el.style.setProperty('--reveal-delay',(i%3*60)+'ms');revealObserver.observe(el)}});
reduce.addEventListener('change',e=>{if(e.matches){targets.forEach(el=>el.classList.add('visible'));revealObserver?.disconnect()}},{once:true});
}
if('IntersectionObserver' in window){sectionObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.navigation a').forEach(a=>a.classList.toggle('current',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('#services,#process,#about,#contact').forEach(el=>sectionObserver.observe(el))}
}
// Keep native touch and trackpad momentum; soften only discrete mouse-wheel steps.
function setupWheelGlide(){
const root=document.documentElement;
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const fine=matchMedia('(hover: hover) and (pointer: fine)');
let frame=0,target=scrollY,last=0;
const stop=()=>{if(frame)cancelAnimationFrame(frame);frame=0;target=scrollY;root.classList.remove('wheel-gliding')};
const tick=now=>{
 const dt=Math.min(40,Math.max(1,now-last));last=now;
 target=Math.max(0,Math.min(target,root.scrollHeight-innerHeight));
 const gap=target-scrollY;
 if(Math.abs(gap)<.75){window.scrollTo({top:target,behavior:'instant'});stop();return}
 const next=scrollY+gap*(1-Math.exp(-dt/85));
 window.scrollTo({top:next,behavior:'instant'});
 frame=requestAnimationFrame(tick);
};
window.addEventListener('wheel',e=>{
 const node=e.target instanceof Element?e.target:null;
 const nativeInput=e.deltaMode===0&&(Math.abs(e.deltaY)<50||!Number.isInteger(e.deltaY));
 if(e.defaultPrevented||!e.cancelable||reduce.matches||!fine.matches||e.ctrlKey||e.metaKey||e.shiftKey||Math.abs(e.deltaX)>0||nativeInput){stop();return}
 if(node?.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="dialog"]')){stop();return}
 for(let el=node;el&&el!==document.body&&el!==root;el=el.parentElement){
  if(el.scrollHeight>el.clientHeight+1&&/auto|scroll|overlay/.test(getComputedStyle(el).overflowY)){stop();return}
 }
 const delta=e.deltaY*(e.deltaMode===1?18:e.deltaMode===2?innerHeight:1);
 const limit=Math.max(0,root.scrollHeight-innerHeight);
 if(!delta||(scrollY<=0&&delta<0)||(scrollY>=limit-1&&delta>0)){stop();return}
 e.preventDefault();
 if(!frame||Math.sign(delta)!==Math.sign(target-scrollY))target=scrollY;
 target=Math.max(0,Math.min(limit,target+delta));
 if(!frame){root.classList.add('wheel-gliding');last=performance.now();frame=requestAnimationFrame(tick)}
},{passive:false});
for(const event of ['pointerdown','touchstart','keydown','click','hashchange','resize','blur','pagehide'])window.addEventListener(event,stop,{passive:true});
reduce.addEventListener('change',stop);fine.addEventListener('change',stop);
}
// Native scroll retained for the Folira presentation.
const originalRender=render;render=function(){originalRender();requestAnimationFrame(setupMotion)};setupMotion();

function closeMobileMenu(restoreFocus=false){const button=document.querySelector('.menu-toggle');document.querySelector('.header')?.classList.remove('menu-open');button?.setAttribute('aria-expanded','false');if(button){button.setAttribute('aria-label',DATA[lang].menuLabel);if(restoreFocus)button.focus()}}
document.addEventListener('click',e=>{const button=e.target.closest('.menu-toggle');if(button){const open=button.getAttribute('aria-expanded')!=='true';document.querySelector('.header').classList.toggle('menu-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?DATA[lang].menuClose:DATA[lang].menuLabel);return}if(e.target.closest('.menu-panel a'))closeMobileMenu();else if(!e.target.closest('.header'))closeMobileMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileMenu(true)});
